// alwaysOutputData:true liefert bei 0 offenen Zeilen ein Platzhalter-Item ohne id - anhand
// des Pflichtfelds id von einem echten Treffer unterscheiden (gleiches Prinzip wie in
// Workflow 15/16).
const items = $input.all().map(i => i.json).filter(j => j && j.id !== undefined && j.id !== null);
if (items.length === 0) {
  return [{ json: { _placeholder: true } }];
}
return items;

// Baut das news_batch-Array fuer die KI. Anders als 03 wird betroffene_ticker NICHT von der
// KI neu ermittelt (Halluzinationsrisiko), sondern die bereits deterministisch in Workflow 16
// ermittelte Zuordnung (vorgeschlagene_ticker) wird der KI zur PRUEFUNG vorgelegt - sie
// bestaetigt oder verwirft, erfindet aber keine neuen Ticker.
const items = $input.all().map(i => i.json);
const news_batch = items.map(j => ({
  id: j.id,
  titel: j.title,
  beschreibung: j.raw_content || '',
  vorgeschlagene_ticker: Array.isArray(j.linked_tickers_json) ? j.linked_tickers_json : (Array.isArray(j.ambiguous_candidates_json) ? j.ambiguous_candidates_json : []),
  ist_markt_makro: j.is_general_market === true
}));
return [{ json: { news_batch, _originals: items } }];

// Historische KI-Bewertung aufbereiten – zentrale Normalisierung und sichere Kandidatenprüfung.
function getAiText(resp) {
  if (typeof resp === 'string') return resp;
  if (resp && Array.isArray(resp.output)) {
    const msg = resp.output.find(o => o.type === 'message');
    const part = msg && Array.isArray(msg.content) ? msg.content.find(c => c.type === 'output_text') : null;
    if (part && part.text) return part.text;
  }
  if (resp && Array.isArray(resp.choices) && resp.choices[0] && resp.choices[0].message) return resp.choices[0].message.content || '';
  if (resp && typeof resp.content === 'string') return resp.content;
  return JSON.stringify(resp || '');
}
function parseKiArray(text) {
  const value = String(text || '').trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  try { const parsed = JSON.parse(value); if (Array.isArray(parsed)) return parsed; } catch {}
  const start = value.indexOf('['), end = value.lastIndexOf(']');
  if (start >= 0 && end > start) { try { const parsed = JSON.parse(value.slice(start, end + 1)); if (Array.isArray(parsed)) return parsed; } catch {} }
  return null;
}
function numberInRange(value, min, max) {
  if (value === null || value === undefined || value === '') return null;
  const number = Number(typeof value === 'string' ? value.replace('%', '').trim() : value);
  return Number.isFinite(number) ? Math.min(max, Math.max(min, number)) : null;
}
function key(value) { return String(value || '').trim().toLocaleLowerCase('de-DE').replace(/[^\p{L}\p{N}]+/gu, '_').replace(/^_+|_+$/g, ''); }
function mapValue(value, mapping, fallback) { return mapping[key(value)] || fallback; }
const MAP = {
  relevanz: { relevant:'mittel', high:'hoch', hoch:'hoch', medium:'mittel', mittel:'mittel', low:'niedrig', niedrig:'niedrig', irrelevant:'irrelevant' },
  ebene: { einzeltitel:'einzeltitel', einzelwert:'einzeltitel', unternehmen:'einzeltitel', company:'einzeltitel', sektor:'sektor', branche:'sektor', sector:'sektor', markt:'markt', market:'markt', makro:'makro', macro:'makro', unklar:'unklar', unbekannt:'unklar', keine:'unklar', nicht_anwendbar:'unklar', kein_klarebene:'unklar', keine_klare_ebene:'unklar' },
  richtung: { positiv:'positiv', positive:'positiv', steigend:'positiv', leicht_positiv:'positiv', negativ:'negativ', negative:'negativ', fallend:'negativ', leicht_negativ:'negativ', neutral:'neutral', keine:'neutral', unklar:'unklar', unknown:'unklar', unbekannt:'unklar' },
  staerke: { hoch:'hoch', stark:'hoch', high:'hoch', mittel:'mittel', moderat:'mittel', medium:'mittel', niedrig:'niedrig', gering:'niedrig', leicht:'niedrig', schwach:'niedrig', low:'niedrig', keine:'niedrig', unklar:'unklar', unknown:'unklar', unbekannt:'unklar' },
  tickerstatus: { bestaetigt:'bestaetigt', bestätigt:'bestaetigt', confirmed:'bestaetigt', false_positive:'false_positive', falsch_positiv:'false_positive', fehlbezug:'false_positive', unklar:'unklar', unclear:'unklar' },
  kategorie: {
    quarterly_results:'quarterly_results', quartalszahlen:'quarterly_results', jahreszahlen:'quarterly_results', halbjahreszahlen:'quarterly_results', geschäftszahlen_operatives:'quarterly_results', geschaeftszahlen_operatives:'quarterly_results', geschäftszahlen:'quarterly_results', geschaeftszahlen:'quarterly_results',
    profit_warning:'profit_warning', gewinnwarnung:'profit_warning', forecast_change:'forecast_change', prognoseänderung:'forecast_change', prognoseaenderung:'forecast_change', guidance:'forecast_change',
    merger_acquisition:'merger_acquisition', übernahme:'merger_acquisition', uebernahme:'merger_acquisition', fusion:'merger_acquisition', akquisition:'merger_acquisition',
    regulation:'regulation', regulierung:'regulation', gesetzgebung:'regulation', management_change:'management_change', managementwechsel:'management_change', vorstandswechsel:'management_change', ceo_wechsel:'management_change',
    legal_dispute:'legal_dispute', gerichtsverfahren:'legal_dispute', rechtsstreit:'legal_dispute', klage:'legal_dispute', product_news:'product_news', produktmeldung:'product_news', produktneuigkeit:'product_news', produktrückruf:'product_news', produktrueckruf:'product_news', strategische_partnerschaft:'product_news',
    macro:'macro', makro:'macro', geopolitics:'geopolitics', geopolitik:'geopolitics', analyst_rating:'analyst_rating', analystenkommentar:'analyst_rating', analystenrating:'analyst_rating', analysteneinstufung:'analyst_rating',
    other:'other', sonstiges:'other', sport:'other', unterhaltung:'other', produkttest:'other', produktrezension:'other', stellenanzeige:'other', stellenanzeigen:'other', kapitalmaßnahme:'other', kapitalmassnahme:'other'
  }
};
const FALSE_POSITIVE_TYPES = new Set(['person','sportverein','stadion_veranstaltungsort','produktnutzung','verkehrsunfall','werbung_angebot','allgemeiner_begriff','anderes_unternehmen','mehrdeutiger_markenname','sonstiges']);
function array(value) { return Array.isArray(value) ? [...new Set(value.map(v => String(v || '').trim()).filter(Boolean))] : []; }
function jsonArray(value) { if (Array.isArray(value)) return value; if (typeof value === 'string') { try { const parsed=JSON.parse(value); return Array.isArray(parsed)?parsed:[]; } catch {} } return []; }
function normalizeText(value) { return String(value || '').trim().toLocaleLowerCase('de-DE'); }
function probabilities(pos, neg, neu) {
  let values=[Number(pos),Number(neg),Number(neu)]; if(values.some(v=>!Number.isFinite(v))) return {positive:null,negative:null,neutral:null};
  values=values.map(v=>Math.max(0,v)); const sum=values.reduce((a,b)=>a+b,0); if(!sum) return {positive:null,negative:null,neutral:null};
  return {positive:values[0]/sum,negative:values[1]/sum,neutral:values[2]/sum};
}
function phraseOccurs(title, content, phrase) { return normalizeText(title+'\n'+content).includes(normalizeText(phrase)); }
function unsafePhrase(phrase, proposedTickers, unsafeConfigured, instruments) {
  const normalized=normalizeText(phrase); if(!normalized || normalized.length<4) return true;
  if(normalized.split(/\s+/u).filter(Boolean).length<2) return true; // keine unspezifischen Einzelwörter
  const blocked=new Set(unsafeConfigured.map(normalizeText));
  for(const ticker of proposedTickers) blocked.add(normalizeText(ticker));
  for(const instrument of instruments) {
    if(!proposedTickers.includes(String(instrument.ticker||'').trim())) continue;
    blocked.add(normalizeText(instrument.name));
    for(const alias of jsonArray(instrument.aliases)) blocked.add(normalizeText(alias));
  }
  return blocked.has(normalized);
}

const payload=$('Baue Batch-Payload').item.json;
const originals=Array.isArray(payload._originals)?payload._originals:[];
const rawText=getAiText($json), assessments=parseKiArray(rawText), results=[];
if(!assessments) return originals.map(original=>({json:{_action:'retry',_error:'KI-Antwort nicht als JSON-Array parsebar',news_id:original.id,claim_token:original.assessment_claim_token,assessment_attempt:original.assessment_attempt,max_attempts:original.max_attempts}}));
const byId=new Map(assessments.filter(a=>a && a.id!==undefined && a.id!==null).map(a=>[String(a.id),a]));
for(const original of originals){
  const assessment=byId.get(String(original.id));
  if(!assessment){results.push({json:{_action:'retry',_error:'Keine Bewertung fuer diese News in der KI-Antwort enthalten',news_id:original.id,claim_token:original.assessment_claim_token,assessment_attempt:original.assessment_attempt,max_attempts:original.max_attempts}});continue;}
  const proposed=array(original.linked_tickers_json).length?array(original.linked_tickers_json):array(original.ambiguous_candidates_json);
  const confirmed=array(assessment.bestaetigte_ticker).filter(t=>new Set(proposed).has(t));
  const relevanz=mapValue(assessment.relevanz,MAP.relevanz,'irrelevant');
  const confidence=numberInRange(assessment.relevanz_konfidenz,0,100);
  const probs=probabilities(assessment.wahrscheinlichkeit_positiv,assessment.wahrscheinlichkeit_negativ,assessment.wahrscheinlichkeit_neutral);
  let tickerStatus=mapValue(assessment.tickerbezug_status,MAP.tickerstatus,'unklar');
  if(proposed.length>0&&confirmed.length>0) tickerStatus='bestaetigt';
  if(confirmed.length===0&&tickerStatus==='bestaetigt') tickerStatus='unklar';
  const fpType=FALSE_POSITIVE_TYPES.has(key(assessment.false_positive_typ))?key(assessment.false_positive_typ):null;
  const fpConfidence=numberInRange(assessment.ausschluss_sicherheit,0,100);
  let phrase=typeof assessment.ausschlussphrase==='string'?assessment.ausschlussphrase.trim():null;
  const unsafeConfigured=jsonArray(original.unsafe_phrases_json), instruments=jsonArray(original.instruments_json);
  if(phrase&&(!phraseOccurs(original.title,original.raw_content,phrase)||unsafePhrase(phrase,proposed,unsafeConfigured,instruments))) phrase=null;
  const candidate=tickerStatus==='false_positive'&&proposed.length===1&&confirmed.length===0&&relevanz==='irrelevant'&&confidence>=85&&fpConfidence>=85&&fpType!==null&&phrase!==null;
  results.push({json:{_action:'persist',news_id:original.id,claim_token:original.assessment_claim_token,assessment_attempt:original.assessment_attempt,max_attempts:original.max_attempts,relevant:relevanz!=='irrelevant',relevanz,wirkungsebene:mapValue(assessment.wirkungsebene,MAP.ebene,'unklar'),betroffene_ticker:confirmed,wirkungsrichtung:mapValue(assessment.wirkungsrichtung,MAP.richtung,'unklar'),wirkung_staerke:mapValue(assessment.wirkung_staerke,MAP.staerke,'unklar'),sentiment:typeof assessment.sentiment==='string'?assessment.sentiment:'unklar',konfidenz:confidence,news_kategorie:mapValue(assessment.news_kategorie,MAP.kategorie,'other'),ticker_begruendung:typeof assessment.begruendung_tickerbezug==='string'?assessment.begruendung_tickerbezug:'',wirkungs_begruendung:typeof assessment.begruendung==='string'?assessment.begruendung:'',based_on_full_text:original.has_full_text===true,wahrscheinlichkeit_positiv:probs.positive,wahrscheinlichkeit_negativ:probs.negative,wahrscheinlichkeit_neutral:probs.neutral,vorgeschlagene_ticker:proposed,tickerbezug_status:tickerStatus,false_positive_typ:fpType,ausschlussphrase:phrase,ausschluss_sicherheit:fpConfidence,blacklist_kandidat:candidate,original_title:original.title||'',original_raw_content:original.raw_content||''}});
}
return results;

function pgStr(v){return v===null||v===undefined?'NULL':"'"+String(v).replace(/\u0000/g,'').replace(/'/g,"''")+"'";} function pgNum(v){return v===null||v===undefined||v===''||!Number.isFinite(Number(v))?'NULL':String(Number(v));} function pgBool(v){return v===null||v===undefined?'NULL':v?'TRUE':'FALSE';} function pgJsonb(v){return "'"+JSON.stringify(v===null||v===undefined?[]:v).replace(/\u0000/g,'').replace(/'/g,"''")+"'::jsonb";}
const i=$json;
if(i._action==='persist'){
  const candidate=i.blacklist_kandidat===true&&Array.isArray(i.vorgeschlagene_ticker)&&i.vorgeschlagene_ticker.length===1&&i.ausschlussphrase?`
INSERT INTO trading.news_match_exclusion_candidates (news_id,ticker,title,raw_content,ki_relevanz,ki_konfidenz,ki_begruendung,false_positive_typ,suggested_pattern,suggested_pattern_type,suggested_match_scope,status)
VALUES (${pgNum(i.news_id)},${pgStr(i.vorgeschlagene_ticker[0])},${pgStr(i.original_title)},${pgStr(i.original_raw_content)},${pgStr(i.relevanz)},${pgNum(i.konfidenz)},${pgStr(i.ticker_begruendung)},${pgStr(i.false_positive_typ)},${pgStr(i.ausschlussphrase)},'exact_phrase','title_and_content','pending')
ON CONFLICT (news_id,ticker) DO UPDATE SET title=EXCLUDED.title,raw_content=EXCLUDED.raw_content,ki_relevanz=EXCLUDED.ki_relevanz,ki_konfidenz=EXCLUDED.ki_konfidenz,ki_begruendung=EXCLUDED.ki_begruendung,false_positive_typ=EXCLUDED.false_positive_typ,suggested_pattern=EXCLUDED.suggested_pattern,suggested_pattern_type=EXCLUDED.suggested_pattern_type,suggested_match_scope=EXCLUDED.suggested_match_scope
WHERE trading.news_match_exclusion_candidates.status='pending';`:'';
  i.sql=`BEGIN;
INSERT INTO trading.historical_news_assessments (news_id,relevant,wirkungsebene,betroffene_ticker_json,wirkungsrichtung,wirkung_staerke,sentiment,konfidenz,news_kategorie,ticker_begruendung,wirkungs_begruendung,based_on_full_text,modell_version,prompt_version)
VALUES (${pgNum(i.news_id)},${pgBool(i.relevant)},${pgStr(i.wirkungsebene)},${pgJsonb(i.betroffene_ticker)},${pgStr(i.wirkungsrichtung)},${pgStr(i.wirkung_staerke)},${pgStr(i.sentiment)},${pgNum(i.konfidenz)},${pgStr(i.news_kategorie)},${pgStr(i.ticker_begruendung)},${pgStr(i.wirkungs_begruendung)},${pgBool(i.based_on_full_text)},'gpt-5.4-mini','historische-news-v2-blacklist-learning')
ON CONFLICT (news_id) DO UPDATE SET relevant=EXCLUDED.relevant,wirkungsebene=EXCLUDED.wirkungsebene,betroffene_ticker_json=EXCLUDED.betroffene_ticker_json,wirkungsrichtung=EXCLUDED.wirkungsrichtung,wirkung_staerke=EXCLUDED.wirkung_staerke,sentiment=EXCLUDED.sentiment,konfidenz=EXCLUDED.konfidenz,news_kategorie=EXCLUDED.news_kategorie,ticker_begruendung=EXCLUDED.ticker_begruendung,wirkungs_begruendung=EXCLUDED.wirkungs_begruendung,based_on_full_text=EXCLUDED.based_on_full_text,modell_version=EXCLUDED.modell_version,prompt_version=EXCLUDED.prompt_version;
${candidate}
UPDATE trading.historical_news SET assessment_status='assessed',assessment_claimed_at=NULL,assessment_claim_token=NULL,assessment_next_retry_at=NULL,assessment_last_error=NULL WHERE id=${pgNum(i.news_id)} AND assessment_claim_token=${pgStr(i.claim_token)} RETURNING id AS persisted_news_id;
COMMIT;`;
}else{
  const failed=Number(i.assessment_attempt||0)>=Number(i.max_attempts||3);
  i.sql=`UPDATE trading.historical_news SET assessment_status=${pgStr(failed?'failed':'retry')},assessment_claimed_at=NULL,assessment_claim_token=NULL,assessment_next_retry_at=${failed?'NULL':"now() + interval '10 minutes'"},assessment_last_error=${pgStr(String(i._error||'Unbekannter KI-Fehler').slice(0,2000))} WHERE id=${pgNum(i.news_id)} AND assessment_claim_token=${pgStr(i.claim_token)} RETURNING id AS persisted_news_id;`;
}
return {json:{...i,sql:i.sql}};

